cd /home/claude
bp() { cat newmf/ei_pre.js newmf/pc$1_body.js > newmf/pc$1.js && python3 newmf/build_mf.py pc$1 newmf/pc$1.js "$2" site/pc$1.html; }
[ -f newmf/pc1_body.js ] && bp 1 '{"title":"Producteur et consommateur 1 – Préférences, utilité et TMS","h1":"Préférences, utilité et taux marginal de substitution","course":"Représenter les goûts d&#39;un consommateur : axiomes, fonctions d&#39;utilité, courbes d&#39;indifférence et TMS","ex":"Utilité Cobb-Douglas et substituts parfaits : utilités marginales, TMS et courbes d&#39;indifférence","badge":"MICROÉCONOMIE"}'
[ -f newmf/pc2_body.js ] && bp 2 '{"title":"Producteur et consommateur 2 – Choix optimal et demandes","h1":"Choix optimal du consommateur et fonctions de demande","course":"Contrainte budgétaire, condition de tangence, lagrangien, demandes marshalliennes et solutions en coin","ex":"Choix optimal Cobb-Douglas, utilité indirecte et substituts parfaits","badge":"MICROÉCONOMIE"}'
[ -f newmf/pc3_body.js ] && bp 3 '{"title":"Producteur et consommateur 3 – Effets de substitution et de revenu","h1":"Effets de substitution et de revenu","course":"Décomposer l&#39;effet d&#39;une variation de prix : demande compensée, décompositions de Hicks et de Slutsky","ex":"Hausse ou baisse d&#39;un prix : décompositions de Hicks et de Slutsky pour une utilité Cobb-Douglas","badge":"MICROÉCONOMIE"}'
[ -f newmf/pc4_body.js ] && bp 4 '{"title":"Producteur et consommateur 4 – Élasticités et surplus du consommateur","h1":"Élasticités et surplus du consommateur","course":"Mesurer la sensibilité de la demande, relier élasticité et dépense, calculer le surplus des consommateurs","ex":"Élasticités prix, revenu et croisée, dépense et surplus","badge":"MICROÉCONOMIE"}'
[ -f newmf/pc5_body.js ] && bp 5 '{"title":"Producteur et consommateur 5 – Technologie de production","h1":"Technologie de production","course":"Fonction de production, productivités, rendements d&#39;échelle, isoquantes et TMST","ex":"Productivités, rendements d&#39;échelle et isoquantes d&#39;une Cobb-Douglas","badge":"MICROÉCONOMIE"}'
[ -f newmf/pc6_body.js ] && bp 6 '{"title":"Producteur et consommateur 6 – Minimisation du coût","h1":"Minimisation du coût et fonction de coût","course":"Isocoûts, condition de tangence, demandes conditionnelles de facteurs et fonction de coût","ex":"Demandes conditionnelles, fonction de coût et substitution des facteurs","badge":"MICROÉCONOMIE"}'
[ -f newmf/pc7_body.js ] && bp 7 '{"title":"Producteur et consommateur 7 – Coûts et offre concurrentielle","h1":"Coûts de court terme et offre de la firme concurrentielle","course":"Coûts fixes et variables, seuils de fermeture et de rentabilité, courbe d&#39;offre et surplus du producteur","ex":"Courbes de coût, décision de production et surplus du producteur","badge":"MICROÉCONOMIE"}'
[ -f newmf/pc8_body.js ] && bp 8 '{"title":"Producteur et consommateur 8 – Équilibre partiel et intervention publique","h1":"Équilibre partiel et intervention publique","course":"Équilibre de marché, surplus, taxe et incidence fiscale, prix plafond et prix plancher","ex":"Équilibre, taxe unitaire et prix plafond : surplus et perte sèche","badge":"MICROÉCONOMIE"}'
[ -f newmf/pc9_body.js ] && bp 9 '{"title":"Producteur et consommateur 9 – Équilibre général d&#39;échange","h1":"Équilibre général d&#39;échange : la boîte d&#39;Edgeworth","course":"Allocations, optimum de Pareto, courbe des contrats, équilibre walrasien et théorèmes du bien-être","ex":"Économie d&#39;échange à deux agents Cobb-Douglas","badge":"MICROÉCONOMIE"}'
